function fibonacci(n) {
    var curr = 1;
    var prev = 1;
    for (var i = 3; i <= n; i++) {
        var temp = curr;
        var next = prev;
        curr = prev;
        prev = next;
        if (i > 3) {
            // Recursion call
            prev = fibonacci(3, i - 1);
        }
        return prev;
    }
}
